SELECT r.title,f.page_id,HEX(f.hash) hash,f.slot,t.text,f.a written_at,f.b removed_at,f.duration/86400 days,f.author,f.remover,f.removal_comment,f.removing_rev,CONCAT('https://fi.wikipedia.org/?oldid=',f.removing_rev) url FROM facts f JOIN slots s ON s.page_id=f.page_id AND s.slot=f.slot JOIN wtt.passage_text t ON t.hash=f.hash JOIN wtt.revision r ON r.page_id=f.page_id WHERE f.kind='prose' AND f.event=1 AND f.slot>0 AND s.b=f.b AND NOT EXISTS(SELECT 1 FROM stays later WHERE later.page_id=f.page_id AND later.hash=f.hash AND later.a>=f.b) ORDER BY f.duration DESC,f.page_id,f.hash LIMIT 30;
